#include <linux/netdevice.h>
#include <linux/slab.h>

int sit_net_init(struct net *net)
{
    struct net_device *dev;

    if (!net)
        return -EINVAL;

    if (net->sit_net && net->sit_net->fallback_dev)
        return 0;

    dev = alloc_netdev(sizeof(struct sit_net), "sit%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev)
        return -ENOMEM;

    dev->flags = IFF_TUNNEL | IFF_UP;
    dev->type = ARPHRD_SIT;
    dev->mtu = 1500;

    if (register_netdev(dev)) {
        free_netdev(dev);
        return -EIO;
    }

    if (!net->sit_net)
        net->sit_net = kmalloc(sizeof(*net->sit_net), GFP_KERNEL);

    if (!net->sit_net) {
        unregister_netdev(dev);
        free_netdev(dev);
        return -ENOMEM;
    }

    net->sit_net->fallback_dev = dev;

    return 0;
}
